// Builds the seed SQL for the demo register. Kept separate from scripts/ so a test can check
// supabase/seed.sql is up to date.
import { demoRegister } from "@/lib/validation/demo-register";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;

export function buildSeedSql(): string {
  const { funds, accounts, callers } = demoRegister;
  const lines = [
    "-- GENERATED by scripts/gen-seed.ts from lib/validation/demo-register.ts. Do not edit by hand.",
    "-- Fund ISINs and names are real public UCITS ETFs; currencies, cut-offs, accounts, people and phones are synthetic.",
    "",
    "truncate public.authorised_callers, public.accounts, public.funds cascade;",
    "",
    "insert into public.funds (isin, name, share_class_currencies, cutoff_time) values",
    funds
      .map((f) => `  (${q(f.isin)}, ${q(f.name)}, array[${f.share_class_currencies.map(q).join(", ")}], ${q(f.cutoff_time)})`)
      .join(",\n") + ";",
    "",
    "insert into public.accounts (account_no, account_name) values",
    accounts.map((a) => `  (${q(a.account_no)}, ${q(a.account_name)})`).join(",\n") + ";",
    "",
    "insert into public.authorised_callers (account_no, name, phone, is_nominated_callback) values",
    callers
      .map((c) => `  (${q(c.account_no)}, ${q(c.name)}, ${q(c.phone)}, ${c.is_nominated_callback})`)
      .join(",\n") + ";",
    "",
    "insert into public.subscriptions (desk_id, status) values ('desk_demo', 'inactive')",
    "  on conflict (desk_id) do nothing;",
    "",
  ];
  return lines.join("\n");
}
